// ctx scoped launcher "@NAME@" — generated by `ctx make launcher` from ctx's reviewed template
// (template version @TEMPLATE_VERSION@). It starts one program, in one folder, under this
// launcher's own macOS identity, so a permission granted to this file (e.g. Full Disk Access)
// applies only to what it starts, never to the terminal or to anything else you run.
//
// How it works (the same two stages as Charles's sysadmin-agent launcher):
//   1. Stage 1 re-spawns this executable with "responsibility" disclaimed, so stage 2 is its own
//      responsible process for macOS privacy checks instead of the terminal.
//   2. Stage 2 checks the program is still the one this launcher was built for (code signature
//      or file hash), moves to the folder, sets a fixed PATH, and spawns the program as its
//      child, staying alive as its parent so the program inherits this launcher's identity. It
//      forwards job control (Ctrl-C reaches the program; Ctrl-Z stops both; `fg` resumes).
//
// Arguments: @ARGUMENT_POLICY_TEXT@
//
// Build: ./build.sh (rebuilding an ad-hoc signed launcher changes its identity: grant it again).

#include <CoreFoundation/CoreFoundation.h>
#include <CommonCrypto/CommonDigest.h>
#include <Security/Security.h>
#include <dlfcn.h>
#include <errno.h>
#include <fcntl.h>
#include <libproc.h>
#include <limits.h>
#include <mach-o/dyld.h>
#include <signal.h>
#include <spawn.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/sysctl.h>
#include <sys/wait.h>
#include <unistd.h>

extern char **environ;

#define NAME "@NAME@"
#define PROGRAM "@PROGRAM@"
#define FOLDER "@FOLDER@"
#define REQUIREMENT "@REQUIREMENT@"
#define SHA256_HEX "@SHA256@"
#define ANY_ARGUMENTS @ANY_ARGUMENTS@
#define FIXED_PATH "@PATH@"
#define CTX "@CTX@"
#define STAGE "CTX_LAUNCHER_STAGE"

static const char *AGENTS[] = {"claude", "codex", "gemini", "agy", "antigravity", "cursor-agent", "aider", "opencode", "goose", NULL};

static void fail(const char *msg) {
    fprintf(stderr, "%s: %s\n", NAME, msg);
}

static int is_agent_name(const char *s) {
    if (!s || !*s) return 0;
    const char *base = strrchr(s, '/');
    base = base ? base + 1 : s;
    for (int i = 0; AGENTS[i]; i++) {
        size_t n = strlen(AGENTS[i]);
        if (strncasecmp(base, AGENTS[i], n) == 0 && (base[n] == 0 || base[n] == '-' || base[n] == '.')) return 1;
    }
    return 0;
}

static int path_is_agent(const char *path) {
    for (int i = 0; AGENTS[i]; i++) {
        char needle[64];
        snprintf(needle, sizeof needle, "/%s/versions/", AGENTS[i]);
        if (strstr(path, needle)) return 1;
    }
    return is_agent_name(path);
}

static int arg0_is_agent(pid_t pid) {
    int mib[3] = {CTL_KERN, KERN_PROCARGS2, pid};
    size_t size = 0;
    if (sysctl(mib, 3, NULL, &size, NULL, 0) != 0 || size < 8) return 0;
    char *buf = malloc(size);
    if (!buf) return 0;
    int found = 0;
    if (sysctl(mib, 3, buf, &size, NULL, 0) == 0) {
        char *p = buf + sizeof(int);
        char *end = buf + size;
        while (p < end && *p) p++;  // executable path
        while (p < end && !*p) p++; // padding
        if (p < end) found = is_agent_name(p);
    }
    free(buf);
    return found;
}

// Walk the parent chain: is an agent among our ancestors, and are we inside a ctx tab?
static int agent_in_ancestry(int *under_ctx) {
    pid_t pid = getppid();
    for (int i = 0; i < 64 && pid > 1; i++) {
        struct proc_bsdinfo info;
        if (proc_pidinfo(pid, PROC_PIDTBSDINFO, 0, &info, sizeof info) != (int)sizeof info) break;
        char path[PROC_PIDPATHINFO_MAXSIZE];
        path[0] = 0;
        proc_pidpath(pid, path, sizeof path);
        if (is_agent_name(info.pbi_name) || is_agent_name(info.pbi_comm) || path_is_agent(path) || arg0_is_agent(pid)) return 1;
        if (strcmp(info.pbi_comm, "ctx-launch") == 0 || strcmp(info.pbi_name, "ctx-launch") == 0) *under_ctx = 1;
        pid = (pid_t)info.pbi_ppid;
    }
    return 0;
}

typedef int (*disclaim_fn)(posix_spawnattr_t *, int);

// Inside a ctx tab, a command typed by an agent through `ctx run` looks exactly like one typed
// by a person, so ask the ctx server who ran it. Runs ctx disclaimed (it gets none of this
// launcher's permissions). Returns 1 for a person, 0 for an agent or no answer.
static int ctx_says_person(void) {
    if (!*CTX) return 0;
    int fds[2];
    if (pipe(fds) != 0) return 0;
    posix_spawn_file_actions_t actions;
    posix_spawn_file_actions_init(&actions);
    posix_spawn_file_actions_adddup2(&actions, fds[1], 1);
    posix_spawn_file_actions_addopen(&actions, 2, "/dev/null", O_WRONLY, 0);
    posix_spawn_file_actions_addclose(&actions, fds[0]);
    posix_spawnattr_t attr;
    posix_spawnattr_init(&attr);
    disclaim_fn f = (disclaim_fn)dlsym(RTLD_DEFAULT, "responsibility_spawnattrs_setdisclaim");
    if (!f || f(&attr, 1) != 0) {
        posix_spawnattr_destroy(&attr);
        posix_spawn_file_actions_destroy(&actions);
        close(fds[0]);
        close(fds[1]);
        return 0;
    }
    char pidtext[32];
    snprintf(pidtext, sizeof pidtext, "%d", (int)getpid());
    char *argv[] = {"ctx", "launcher-check", pidtext, NULL};
    pid_t child;
    int rc = posix_spawn(&child, CTX, &actions, &attr, argv, environ);
    posix_spawnattr_destroy(&attr);
    posix_spawn_file_actions_destroy(&actions);
    close(fds[1]);
    if (rc != 0) {
        close(fds[0]);
        return 0;
    }
    char answer[32] = {0};
    ssize_t n = read(fds[0], answer, sizeof answer - 1);
    close(fds[0]);
    int st;
    waitpid(child, &st, 0);
    return n > 0 && strncmp(answer, "person", 6) == 0;
}

static int arguments_allowed(void) {
    if (ANY_ARGUMENTS) return 1;
    if (!isatty(0)) return 0;
    int under_ctx = 0;
    if (agent_in_ancestry(&under_ctx)) return 0;
    if (under_ctx) return ctx_says_person();
    return 1;
}

// Is the program still the one this launcher was built for?
static int program_is_trusted(const char *resolved) {
    if (*REQUIREMENT) {
        CFURLRef url = CFURLCreateFromFileSystemRepresentation(NULL, (const UInt8 *)resolved, (CFIndex)strlen(resolved), false);
        SecStaticCodeRef code = NULL;
        SecRequirementRef req = NULL;
        CFStringRef text = CFStringCreateWithCString(NULL, REQUIREMENT, kCFStringEncodingUTF8);
        int ok = url && text && SecStaticCodeCreateWithPath(url, kSecCSDefaultFlags, &code) == errSecSuccess &&
                 SecRequirementCreateWithString(text, kSecCSDefaultFlags, &req) == errSecSuccess &&
                 SecStaticCodeCheckValidity(code, kSecCSCheckAllArchitectures, req) == errSecSuccess;
        if (code) CFRelease(code);
        if (req) CFRelease(req);
        if (text) CFRelease(text);
        if (url) CFRelease(url);
        return ok;
    }
    int fd = open(resolved, O_RDONLY);
    if (fd < 0) return 0;
    CC_SHA256_CTX ctx;
    CC_SHA256_Init(&ctx);
    unsigned char buf[65536];
    ssize_t n;
    while ((n = read(fd, buf, sizeof buf)) > 0) CC_SHA256_Update(&ctx, buf, (CC_LONG)n);
    close(fd);
    unsigned char digest[CC_SHA256_DIGEST_LENGTH];
    CC_SHA256_Final(digest, &ctx);
    char hex[CC_SHA256_DIGEST_LENGTH * 2 + 1];
    for (int i = 0; i < CC_SHA256_DIGEST_LENGTH; i++) snprintf(hex + i * 2, 3, "%02x", digest[i]);
    return strcmp(hex, SHA256_HEX) == 0;
}

static int spawn_and_wait(const char *path, char *const argv[], int disclaim) {
    posix_spawnattr_t attr;
    posix_spawnattr_init(&attr);
    sigset_t def;
    sigemptyset(&def);
    sigaddset(&def, SIGINT);
    sigaddset(&def, SIGQUIT);
    posix_spawnattr_setsigdefault(&attr, &def);
    posix_spawnattr_setflags(&attr, POSIX_SPAWN_SETSIGDEF);
    if (disclaim) {
        disclaim_fn f = (disclaim_fn)dlsym(RTLD_DEFAULT, "responsibility_spawnattrs_setdisclaim");
        if (!f || f(&attr, 1) != 0) {
            fail("this macOS can't give the launcher its own identity; refusing to run under the terminal's");
            return 1;
        }
    }
    pid_t pid;
    int rc = posix_spawn(&pid, path, NULL, &attr, argv, environ);
    posix_spawnattr_destroy(&attr);
    if (rc != 0) {
        fprintf(stderr, "%s: can't start %s: %s\n", NAME, path, strerror(rc));
        return 127;
    }
    signal(SIGINT, SIG_IGN);
    signal(SIGQUIT, SIG_IGN);
    for (;;) {
        int st;
        if (waitpid(pid, &st, WUNTRACED) < 0) {
            if (errno == EINTR) continue;
            return 1;
        }
        if (WIFSTOPPED(st)) {
            kill(getpid(), SIGSTOP);
            continue;
        }
        return WIFEXITED(st) ? WEXITSTATUS(st) : 128 + WTERMSIG(st);
    }
}

int main(int argc, char *argv[]) {
    if (!getenv(STAGE)) {
        if (argc > 1 && !arguments_allowed()) {
            fail("arguments are accepted only when a person runs this launcher at a terminal, not from agents. Run it with no arguments.");
            return 2;
        }
        char raw[PATH_MAX], self[PATH_MAX];
        uint32_t n = sizeof raw;
        if (_NSGetExecutablePath(raw, &n) != 0 || !realpath(raw, self)) {
            fail("can't find its own path");
            return 1;
        }
        setenv(STAGE, "2", 1);
        return spawn_and_wait(self, argv, 1);
    }
    unsetenv(STAGE);

    // No environment-variable tricks: a fixed PATH, no dynamic-loader overrides.
    for (char **e = environ; *e;) {
        if (strncmp(*e, "DYLD_", 5) == 0) {
            char key[256];
            size_t k = strcspn(*e, "=");
            if (k >= sizeof key) k = sizeof key - 1;
            memcpy(key, *e, k);
            key[k] = 0;
            unsetenv(key);
            continue;
        }
        e++;
    }
    setenv("PATH", FIXED_PATH, 1);
    setenv("CTX_LAUNCHER", NAME, 1);

    char resolved[PATH_MAX];
    if (!realpath(PROGRAM, resolved)) {
        fail("the program it was built for is missing: " PROGRAM);
        return 1;
    }
    if (!program_is_trusted(resolved)) {
        fail("the program on disk isn't the one this launcher was built for (signature or contents changed). Rebuild it: ctx rebuild launcher \"" NAME "\"");
        return 1;
    }
    if (chdir(FOLDER) != 0) {
        fail("can't enter its folder: " FOLDER);
        return 1;
    }
    char **pargv = calloc((size_t)argc + 1, sizeof *pargv);
    const char *base = strrchr(PROGRAM, '/');
    pargv[0] = (char *)(base ? base + 1 : PROGRAM);
    for (int i = 1; i < argc; i++) pargv[i] = argv[i];
    return spawn_and_wait(resolved, pargv, 0);
}
